#include "treebuilder/element-type.h"

/* Auto-generated by `gperf`. */
#include "treebuilder/autogenerated-element-type.c"

static int quill_name_is(const hubbub_string *n, const char *lower)
{
	size_t i;
	for (i = 0; i < n->len; i++) {
		unsigned char c = n->ptr[i];
		if (c >= 'A' && c <= 'Z') c = (unsigned char) (c - 'A' + 'a');
		if (lower[i] == '\0' || c != (unsigned char) lower[i]) return 0;
	}
	return lower[n->len] == '\0';
}

/* Exported function, documented in element-type.h */
element_type element_type_from_name(
		hubbub_treebuilder *treebuilder,
		const hubbub_string *tag_name)
{
	const struct element_type_map *value;

	UNUSED(treebuilder);

	value = hubbub_element_type_generated_lookup(
			(const char *)tag_name->ptr,
			tag_name->len);
	if (value == NULL) {
		/* Quill: <source> and <track> postdate the generated table; without them the parser nested everything
		 * after a <picture>'s or <video>'s first <source> inside it. */
		if (quill_name_is(tag_name, "source"))
			return SOURCE;
		if (quill_name_is(tag_name, "track"))
			return TRACK;
		return UNKNOWN;
	}

	return value->type;
}

/**
 * Convert an element type to a name
 *
 * \param type  The element type
 * \return Pointer to name
 */
const char *element_type_to_name(element_type type)
{
	size_t i;

	for (i = 0; i < sizeof(wordlist) / sizeof(wordlist[0]); i++) {
		if (wordlist[i].type == type) {
			return wordlist[i].name;
		}
	}

	return "UNKNOWN";
}
